import sys
from collections import deque

def num_squares_brute(n):
    if n == 0: return 0
    if int(n ** 0.5) ** 2 == n: return 1
    sqrs = [i * i for i in range(1, int(n ** 0.5) + 1)]
    q = deque([n])
    levels = {n: 1}
    while q:
        m = q.popleft()
        for s in sqrs:
            if m - s < 0: continue
            if m - s == 0: return levels[m]
            if m - s not in levels:
                levels[m - s] = levels[m] + 1
                q.append(m - s)
    return 0

if __name__ == '__main__':
    n = int(sys.stdin.readline().strip())
    print(num_squares_brute(n))

import sys

def num_squares_opt(n):
    dp = [0] * (n + 1)
    sqrs = [i * i for i in range(1, int(n ** 0.5) + 1)]
    for i in range(1, n + 1):
        dp[i] = float('inf')
        for s in sqrs:
            if s > i: break
            dp[i] = min(dp[i], dp[i - s] + 1)
    return dp[n]

if __name__ == '__main__':
    n = int(sys.stdin.readline().strip())
    print(num_squares_opt(n))

import sys

def num_squares_best(n):
    import math
    sq = int(math.isqrt(n))
    if sq * sq == n:
        return 1
    m = n
    while m % 4 == 0:
        m //= 4
    if m % 8 == 7:
        return 4
    for i in range(1, int(math.isqrt(n)) + 1):
        s = i * i
        d = int(math.isqrt(n - s))
        if d * d + s == n:
            return 2 if i > 0 or d > 0 else 1
    return 3

if __name__ == '__main__':
    n = int(sys.stdin.readline().strip())
    print(num_squares_best(n))
